from socket import timeout as TimeoutError, error as SocketError
from telnetlib import Telnet

from .exceptions import IncorrectScpiCommand, ScpiCommandSendingError, ScpiOutputReadingError, \
    ScpiConnectionError


class ScpiClient(object):
    """
    Enables SCPI communication with given IP address and port number using Telnet connection.
    """
    def __init__(self, ip, port):
        self._ip = ip
        self._port = port
        self._connection = Telnet()

    def execute_command(self, cmd, timeout=10):
        """
        Opens SCPI connection over Telnet, sends SCPI command and closes SCPI connection.
        :param cmd: SCPI command which will be executed
        :type cmd: str
        :param timeout: time to wait for individual steps of executing command to be finished; defaults to 10 seconds
        :type timeout: int
        :raises IncorrectScpiCommand: when given SCPI command is invalid
        :raises ValueError: when timeout is None
        :raises ScpiConnectionError: when SCPI connection can't be opened
        :raises ScpiCommandSendingError: when SCPI command can't be send
        """
        self._check_command(cmd)
        self._check_timeout(timeout)
        self._open_connection(timeout)
        try:
            self._send(cmd)
        finally:
            self._close_connection()

    def execute_query(self, query, timeout=10):
        """
        Opens SCPI connection over Telnet, executes SCPI query, reads it's output and closes SCPI connection.
        :param query: SCPI query which will be executed
        :type query: str
        :param timeout: time to wait for individual steps of executing query to be finished; defaults to 10 seconds
        :type timeout: int
        :return: output of executed SCPI query
        :rtype: str
        :raises IncorrectScpiCommand: when given SCPI query is invalid
        :raises ValueError: when timeout is None
        :raises ScpiConnectionError: when SCPI connection can't be opened
        :raises ScpiCommandSendingError: when SCPI query can't be send
        :raises ScpiOutputReadingError: when SCPI query's output can't be read
        """
        self._check_command(query)
        self._check_timeout(timeout)
        self._open_connection(timeout)
        try:
            self._send(query)
            output = self._read_output(timeout)
        finally:
            self._close_connection()
        return output.decode('utf8')

    @staticmethod
    def _check_command(cmd):
        """
        Checks whether SCPI command is not None nor empty string.
        :param cmd: SCPI command which will be checked
        :type cmd: str
        :raises IncorrectScpiCommand: when given SCPI command is empty
        """
        if not cmd:
            raise IncorrectScpiCommand("Unable to execute incorrect SCPI command: '{}'".format(cmd))

    @staticmethod
    def _check_timeout(timeout):
        """
        Checks whether timeout is not None.
        :param timeout: timeout which will be checked
        :type timeout: int
        :raises ValueError: when timeout is None
        """
        if timeout is None:
            raise ValueError("Timeout for executing SCPI command can't be None")

    def _open_connection(self, timeout):
        """
        Opens SCPI connection over Telnet.
        :param timeout: time to wait (in seconds) for connection to be opened
        :type timeout: int
        :raises ScpiConnectionError: when SCPI connection can't be opened
        """
        try:
            self._connection.open(self._ip, self._port, timeout=timeout)
        except (TimeoutError, SocketError):
            raise ScpiConnectionError("Unable to open connection to {}:{}".format(self._ip, self._port))

    def _send(self, cmd):
        """
        Sends SCPI command over opened SCPI connection.
        :param cmd: SCPI command which will be send
        :type cmd: str
        :raises ScpiCommandSendingError: when SCPI command can't be send
        """
        try:
            self._connection.write(cmd.encode('utf8') + b'\r\n')
        except SocketError:
            raise ScpiCommandSendingError("Unable to send command '{}'".format(cmd))

    def _read_output(self, timeout):
        """
        Reads SCPI query output from opened SCPI connection.
        :param timeout: time to wait (in seconds) for output to be available
        :type timeout: int
        :raises ScpiOutputReadingError: when SCPI query's output can't be read
        """
        try:
            return self._connection.read_until(b'\n', timeout=timeout).rstrip()
        except EOFError:
            raise ScpiOutputReadingError("Unable to read query's output")

    def _close_connection(self):
        """
        Closes SCPI connection over Telnet.
        """
        self._connection.close()
